create table if not exists public.ai_conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Nueva conversación',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ai_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.ai_conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('user','assistant')),content text not null,created_at timestamptz not null default now());
alter table public.ai_conversations enable row level security;alter table public.ai_messages enable row level security;
create policy "AI conversations owner select" on public.ai_conversations for select to authenticated using((select auth.uid())=user_id);
create policy "AI conversations owner insert" on public.ai_conversations for insert to authenticated with check((select auth.uid())=user_id);
create policy "AI conversations owner update" on public.ai_conversations for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "AI conversations owner delete" on public.ai_conversations for delete to authenticated using((select auth.uid())=user_id);
create policy "AI messages owner select" on public.ai_messages for select to authenticated using((select auth.uid())=user_id);
create policy "AI messages owner insert" on public.ai_messages for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.ai_conversations c where c.id=conversation_id and c.user_id=(select auth.uid())));
create policy "AI messages owner delete" on public.ai_messages for delete to authenticated using((select auth.uid())=user_id);
create table if not exists public.school_grades(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.school_students(id) on delete cascade,subject_id uuid not null references public.school_subjects(id) on delete restrict,teacher_id uuid references public.school_teachers(id) on delete set null,period text not null,activity text not null,value numeric(4,2) not null check(value between 0 and 5),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists school_grades_student_idx on public.school_grades(student_id,created_at desc);alter table public.school_grades enable row level security;
create policy "Grades student read own" on public.school_grades for select to authenticated using(exists(select 1 from public.school_students s join public.school_profiles p on p.id=s.profile_id where s.id=student_id and p.auth_user_id=(select auth.uid())));
create policy "Grades teacher read own" on public.school_grades for select to authenticated using(exists(select 1 from public.school_teachers t join public.school_profiles p on p.id=t.profile_id where t.id=teacher_id and p.auth_user_id=(select auth.uid())));
create policy "Grades teacher write own" on public.school_grades for all to authenticated using(exists(select 1 from public.school_teachers t join public.school_profiles p on p.id=t.profile_id where t.id=teacher_id and p.auth_user_id=(select auth.uid()))) with check(exists(select 1 from public.school_teachers t join public.school_profiles p on p.id=t.profile_id where t.id=teacher_id and p.auth_user_id=(select auth.uid())));
create table if not exists public.school_assignments(id uuid primary key default gen_random_uuid(),subject_id uuid not null references public.school_subjects(id) on delete restrict,teacher_id uuid references public.school_teachers(id) on delete set null,grade text,group_name text,title text not null,description text,due_at timestamptz,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.school_assignment_submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.school_assignments(id) on delete cascade,student_id uuid not null references public.school_students(id) on delete cascade,status text not null default 'pending' check(status in ('pending','submitted','late')),submitted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,student_id));
alter table public.school_assignments enable row level security;alter table public.school_assignment_submissions enable row level security;
create policy "Assignments student read course" on public.school_assignments for select to authenticated using(exists(select 1 from public.school_profiles p join public.school_students s on s.profile_id=p.id where p.auth_user_id=(select auth.uid()) and p.grade=school_assignments.grade and p.group_name=school_assignments.group_name));
create policy "Assignments teacher manage own" on public.school_assignments for all to authenticated using(exists(select 1 from public.school_teachers t join public.school_profiles p on p.id=t.profile_id where t.id=school_assignments.teacher_id and p.auth_user_id=(select auth.uid()))) with check(exists(select 1 from public.school_teachers t join public.school_profiles p on p.id=t.profile_id where t.id=school_assignments.teacher_id and p.auth_user_id=(select auth.uid())));
create policy "Submissions student manage own" on public.school_assignment_submissions for all to authenticated using(exists(select 1 from public.school_students s join public.school_profiles p on p.id=s.profile_id where s.id=school_assignment_submissions.student_id and p.auth_user_id=(select auth.uid()))) with check(exists(select 1 from public.school_students s join public.school_profiles p on p.id=s.profile_id where s.id=school_assignment_submissions.student_id and p.auth_user_id=(select auth.uid())));
create policy "Submissions teacher read own assignments" on public.school_assignment_submissions for select to authenticated using(exists(select 1 from public.school_assignments a join public.school_teachers t on t.id=a.teacher_id join public.school_profiles p on p.id=t.profile_id where a.id=school_assignment_submissions.assignment_id and p.auth_user_id=(select auth.uid())));